                    <div className="flex items-center space-x-2">

                      <button className={`p-2 rounded-lg transition-colors ${

                        isDarkMode ? 'hover:bg-gray-700' : 'hover:bg-gray-100'

                      }`}>

                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />

                        </svg>

                      </button>

                      <input 

                        type="text" 

                        placeholder="Type your message..." 

                        className={`flex-1 px-3 py-2 rounded-lg border text-sm ${

                          isDarkMode ? 'bg-gray-700 border-gray-600 text-white' : 'bg-white border-gray-300'

                        }`}

                      />

                      <button className="px-3 py-2 bg-gradient-to-r from-purple-500 to-pink-500 text-white font-semibold rounded-lg hover:from-purple-600 hover:to-pink-600 transition-all duration-300">

                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />

                        </svg>

                      </button>

                    </div>

                  </div>

                </div>

              </div>



              {/* Right Column - Support Stats & Contact */}

              <div className="w-80 p-4 space-y-4 overflow-y-auto">

                

                {/* Support Statistics */}

                <div className={`rounded-xl border p-4 ${

                  isDarkMode ? 'bg-gray-800/50 border-gray-700/50' : 'bg-gray-50 border-gray-200/50'

                }`}>

                  <h4 className={`font-semibold text-sm mb-3 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                    Support Statistics

                  </h4>

                  <div className="space-y-3">

                    <div className="flex items-center justify-between">

                      <div className="flex items-center">

                        <div className="w-6 h-6 bg-green-500/20 rounded-lg flex items-center justify-center mr-2">

                          <svg className="w-3 h-3 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />

                          </svg>

                        </div>

                        <span className={`text-xs ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>

                          Avg Response Time

                        </span>

                      </div>

                      <span className="text-xs font-bold text-green-600 dark:text-green-400">

                        &lt; 2 min

                      </span>

                    </div>



                    <div className="flex items-center justify-between">

                      <div className="flex items-center">

                        <div className="w-6 h-6 bg-blue-500/20 rounded-lg flex items-center justify-center mr-2">

                          <svg className="w-3 h-3 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />

                          </svg>

                        </div>

                        <span className={`text-xs ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>

                          24/7 Availability

                        </span>

                      </div>

                      <span className="text-xs font-bold text-blue-600 dark:text-blue-400">

                        Always

                      </span>

                    </div>



                    <div className="flex items-center justify-between">

                      <div className="flex items-center">

                        <div className="w-6 h-6 bg-purple-500/20 rounded-lg flex items-center justify-center mr-2">

                          <svg className="w-3 h-3 text-purple-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />

                          </svg>

                        </div>

                        <span className={`text-xs ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>

                          Satisfaction Rate

                        </span>

                      </div>

                      <span className="text-xs font-bold text-purple-600 dark:text-purple-400">

                        98%

                      </span>

                    </div>



                    <div className="flex items-center justify-between">

                      <div className="flex items-center">

                        <div className="w-6 h-6 bg-pink-500/20 rounded-lg flex items-center justify-center mr-2">

                          <svg className="w-3 h-3 text-pink-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />

                          </svg>

                        </div>

                        <span className={`text-xs ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>

                          Active Agents

                        </span>

                      </div>

                      <span className="text-xs font-bold text-pink-600 dark:text-pink-400">

                        12

                      </span>

                    </div>

                  </div>

                </div>



                {/* Contact Options */}

                <div className={`rounded-xl border p-4 ${

                  isDarkMode ? 'bg-gray-800/50 border-gray-700/50' : 'bg-gray-50 border-gray-200/50'

                }`}>

                  <h4 className={`font-semibold text-sm mb-3 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                    Other Contact Options

                  </h4>

                  <div className="space-y-2">

                    <button className="w-full p-2 rounded-lg bg-gradient-to-r from-green-500 to-emerald-500 text-white text-xs font-semibold hover:from-green-600 hover:to-emerald-600 transition-all duration-300">

                      <div className="flex items-center justify-center">

                        <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />

                        </svg>

                        Call Support

                      </div>

                    </button>



                    <button className="w-full p-2 rounded-lg bg-gradient-to-r from-blue-500 to-cyan-500 text-white text-xs font-semibold hover:from-blue-600 hover:to-cyan-600 transition-all duration-300">

                      <div className="flex items-center justify-center">

                        <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />

                        </svg>

                        Email Support

                      </div>

                    </button>



                    <button className="w-full p-2 rounded-lg bg-gradient-to-r from-purple-500 to-pink-500 text-white text-xs font-semibold hover:from-purple-600 hover:to-pink-600 transition-all duration-300">

                      <div className="flex items-center justify-center">

                        <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.367 2.684 3 3 0 00-5.367-2.684z" />

                        </svg>

                        WhatsApp Support

                      </div>

                    </button>

                  </div>

                </div>



                {/* FAQ Section */}

                <div className={`rounded-xl border p-4 ${

                  isDarkMode ? 'bg-gray-800/50 border-gray-700/50' : 'bg-gray-50 border-gray-200/50'

                }`}>

                  <h4 className={`font-semibold text-sm mb-3 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                    Frequently Asked Questions

                  </h4>

                  <div className="space-y-2">

                    <div className={`p-2 rounded-lg text-xs ${

                      isDarkMode ? 'bg-gray-700' : 'bg-white'

                    }`}>

                      <h5 className={`font-medium mb-1 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                        How do I track my order?

                      </h5>

                      <p className={`${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>

                        Click on "Track my order" above or check your email for tracking details.

                      </p>

                    </div>

                    <div className={`p-2 rounded-lg text-xs ${

                      isDarkMode ? 'bg-gray-700' : 'bg-white'

                    }`}>

                      <h5 className={`font-medium mb-1 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                        What are your delivery hours?

                      </h5>

                      <p className={`${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>

                        We deliver 6 AM to 10 PM, 7 days a week.

                      </p>

                    </div>

                    <div className={`p-2 rounded-lg text-xs ${

                      isDarkMode ? 'bg-gray-700' : 'bg-white'

                    }`}>

                      <h5 className={`font-medium mb-1 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                        How do I cancel my subscription?

                      </h5>

                      <p className={`${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>

                        Go to Account Settings and select "Manage Subscription".

                      </p>

                    </div>

                  </div>

                </div>



              </div>



            </div>



          </div>

        </div>



        </>

    )}



    {/* Scroll to Top Button - Modern Design */}

    {showScrollTop && !chatPopup && (

      <button

        onClick={scrollToTop}

        className="fixed bottom-8 left-1/2 transform -translate-x-1/2 px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-full shadow-2xl hover:shadow-3xl hover:scale-110 transition-all duration-300 flex items-center space-x-2 group"

        style={{ 

          zIndex: 99999

        }}

      >

        <svg 

          className="w-6 h-6 transform transition-transform duration-300 group-hover:-translate-y-1 flex-shrink-0" 

          fill="currentColor" 

          stroke="currentColor" 

          viewBox="0 0 24 24"

        >

          <path 

            strokeLinecap="round" 

            strokeLinejoin="round" 

            strokeWidth={2} 

            d="M5 10l7-7m0 0l7 7m-7-7v18" 

          />

        </svg>

        <span className="font-medium text-sm whitespace-nowrap">Scroll to Top</span>

        {/* Glow Effect */}

        <div className="absolute inset-0 bg-gradient-to-r from-blue-400 to-purple-400 rounded-full opacity-0 group-hover:opacity-30 transition-opacity duration-300 blur-xl"></div>

      </button>

    )}



    </>

  );

};



export default Home;
